    "questionHtml": "Sebuah lini perakitan komponen elektronika SMK beroperasi dengan data harian: Ketersediaan Mesin (Availability Rate) = 90%, Efisiensi Kinerja Mesin (Performance Rate) = 85%, dan Tingkat Kualitas Produk Bebas Cacat (Quality Rate) = 95%. Berapakah nilai Overall Equipment Effectiveness (OEE) mesin tersebut dan bagaimana statusnya terhadap standar kelas dunia (World Class OEE minimal 85%)?",
