    "questionHtml": "Tim wirausaha SMK Desain Produk berniat meluncurkan kursi belajar ergonomis. Berdasarkan riset pasar, harga kompetitif yang bersedia dibayar oleh konsumen (Target Price) adalah Rp250.000 per unit. Manajemen sekolah menetapkan target margin laba kotor yang diharapkan sebesar 30% dari harga jual. Jika estimasi biaya produksi saat ini adalah Rp200.000 per unit, besarnya pengurangan biaya (Cost Reduction Target) yang harus dicapai melalui Rekayasa Nilai (Value Engineering) adalah...",
    "formulaHud": {
      "title": "FORMULA TARGET COSTING (VALUE ENGINEERING)",
      "latex": "\\text{Target Cost} = \\text{Target Price} - \\text{Target Profit}; \\quad \\Delta \\text{Cost} = \\text{Current Cost} - \\text{Target Cost}",
      "legend": "• Target Price = Rp250.000<br>• Target Profit (30%) = $0{,}30 \\times 250.000 = \\text{Rp}75.000$<br>• Target Cost = $250.000 - 75.000 = \\text{Rp}175.000$<br>• Target Pengurangan Biaya = $200.000 - 175.000 = \\text{Rp}25.000$ per unit"
    },
