        "key": "D",
        "text": "Rp25.000 per unit, karena Biaya Target (Target Cost) adalah Rp175.000 (Rp250.000 dikurangi margin laba Rp75.000), sehingga terdapat selisih efisiensi sebesar Rp25.000 dari biaya saat ini Rp200.000."
