    "questionHtml": "Dalam perakitan panel saklar pintar di bengkel SMK, permintaan harian pelanggan adalah 120 unit. Waktu kerja efektif yang tersedia bagi operator dalam satu hari adalah 8 jam kerja (480 menit), dikurangi total istirahat terencana 60 menit (waktu kerja bersih 420 menit atau 25.200 detik). Berapakah Takt Time (ritme detak produksi) yang wajib dipertahankan oleh lini perakitan agar pesanan pelanggan terpenuhi tepat waktu tanpa kelebihan produksi?",
