    "type": "mcq",
    "questionHtml": "Dalam merancang cetakan injeksi plastik untuk bodi stopkontak listrik, tim engineering Teaching Factory SMK menerapkan prinsip Mutu Taguchi (Taguchi Quality Loss Function): $L(y) = k(y - m)^2$. Di mana $m$ adalah nilai target dimensi nominal (50,00 mm) dan $y$ adalah dimensi aktual produk. Filosofi revolusioner Taguchi mengenai kerugian mutu (Quality Loss) yang membedakannya dari pendekatan toleransi tradisional adalah...",
